 $router='<?php require '.var_export($f->root.'/vendor/autoload.php',true).';require '.var_export($f->root.'/vendor/yiisoft/yii2/Yii.php',true).';class HeldPerformanceCommand extends yii\\db\\Command {private static bool $held=false;protected function queryInternal($method,$fetchMode=null){$sql=$this->getRawSql();if(str_contains($sql,"fm2_otiz_calculation_revisions")&&isset($_SERVER["HTTP_X_PERF_HOLD"])&&!self::$held){self::$held=true;file_put_contents('.var_export($held,true).',"ready");$deadline=microtime(true)+8;while(!is_file('.var_export($release,true).')&&microtime(true)<$deadline)usleep(10000);if(!is_file('.var_export($release,true).'))file_put_contents('.var_export($expired,true).',"expired");}return parent::queryInternal($method,$fetchMode);}}$config=require '.var_export($f->root.'/config/yii/web.php',true).';$factory=$config["components"]["db"];$config["components"]["db"]=static function()use($factory){$db=$factory();$db->commandClass=HeldPerformanceCommand::class;return $db;};$app=new yii\\web\\Application($config);$app->on(yii\\base\\Application::EVENT_AFTER_REQUEST,static function(){file_put_contents('.var_export($trace,true).',json_encode(["uri"=>$_SERVER["REQUEST_URI"],"method"=>$_SERVER["REQUEST_METHOD"],"active"=>Yii::$app->session->isActive])."\n",FILE_APPEND|LOCK_EX);});$app->run();';
